@js:
/* 站址自动推导：优先取引擎传入的当前页 URL（换域后自动跟随），取不到才回落。
   ⇒ 换域只需改 sourceUrl 与 header 的 referer，规则本身不用动。 */
var B = (function () {
  var u = (typeof baseUrl !== 'undefined' && baseUrl) ? String(baseUrl) : '';
  var m = u.match(/^https?:\/\/[^\/]+/);
  return m ? m[0] : 'https://hsnd.ubetl.com';
})();
var MARK = 'postmessage_';

function _ok(t) { return !!t && String(t).indexOf(MARK) >= 0; }
function _abs(u) {
  u = String(u || '');
  if (u.indexOf('http') === 0) return u;
  if (!u) return '';
  return B + (u.charAt(0) === '/' ? u : '/' + u);
}

/* 与列表规则同款多路自愈（marker 换成 postmessage_） */
function _heal(url, sid) {
  var hdr = { 'Cookie': '_safe=' + sid, 'Referer': B + '/' };
  var fails = [];
  var t;

  try { t = String(java.get(url, hdr) || ''); if (_ok(t)) return { h: t, how: 'get-obj' }; } catch (e1) {}
  fails.push('get');

  try {
    var hm = new java.util.HashMap();
    hm.put('Cookie', '_safe=' + sid);
    hm.put('Referer', B + '/');
    t = String(java.get(url, hm) || '');
    if (_ok(t)) return { h: t, how: 'get-map' };
  } catch (e2) {}
  fails.push('getMap');

  try {
    if (typeof cookie !== 'undefined' && cookie && cookie.setCookie) {
      cookie.setCookie(B + '/', '_safe=' + sid);
    }
    t = String(java.ajax(url) || '');
    if (_ok(t)) return { h: t, how: 'cookieJar' };
  } catch (e3) {}
  fails.push('cookieJar');

  try {
    if (java.setCookie) { java.setCookie(B + '/', '_safe=' + sid); }
    t = String(java.ajax(url) || '');
    if (_ok(t)) return { h: t, how: 'setCookie' };
  } catch (e4) {}
  fails.push('setCookie');

  try {
    t = String(java.connect(url).header('Cookie', '_safe=' + sid)
               .header('Referer', B + '/').get() || '');
    if (_ok(t)) return { h: t, how: 'connect' };
  } catch (e5) {}
  fails.push('connect');

  try {
    t = String(java.webView(url, '') || '');
    if (_ok(t)) return { h: t, how: 'webview' };
  } catch (e6) {}
  fails.push('webview');

  return { h: '', how: '', fails: fails.join('/') };
}

var html = String(result || '');
var isGate = (html.indexOf('safeid') >= 0 && html.length < 5000);
var diag = '';

if (isGate) {
  var sid = (html.match(/safeid\s*=\s*'([^']+)'/) || [])[1] || '';
  var u = _abs(baseUrl);
  if (sid && u) {
    var r = _heal(u, sid);
    if (_ok(r.h)) { html = r.h; } else { diag = '正文通行证失效，自愈均未成功（' + r.fails + '）'; }
  } else {
    diag = '正文撞门但取不到 safeid 或 baseUrl';
  }
}

if (!_ok(html)) {
  if (!diag) { diag = '正文解析为空（未命中 postmessage）'; }
  result = '<p style="font-size:18px;line-height:1.9;color:#c0392b">⚠️ ' + diag + '</p>';
} else {
  /* —— 切片：必须连 <td …> 一起吃掉，否则首行残留 id="…"> 脏字 —— */
  var m = html.match(/<td[^>]*id="postmessage_\d+"[^>]*>/);
  if (m) {
    html = html.slice(html.indexOf(m[0]) + m[0].length);
  } else {
    var m2 = html.match(/id="postmessage_\d+"/);
    if (m2) { html = html.slice(html.indexOf(m2[0])); }
  }

  var terms = ['id="comment_', '<div class="authi"', '<div class="pct"'];
  var cut = html.length;
  for (var i = 0; i < terms.length; i++) {
    var p = html.indexOf(terms[i]);
    if (p > 0 && p < cut) { cut = p; }
  }
  html = html.slice(0, cut);

  /* 附件区 <ignore_js_op> → 懒加载占位图（file= 与 zoomfile= 同 URL） */
  html = html.replace(/<ignore_js_op>[\s\S]*?<\/ignore_js_op>/g, function (blk) {
    var u2 = blk.match(/(?:zoomfile|file)="([^"]+)"/);
    if (!u2) return '';
    return '<img class="sh-img" data-zurl="' + u2[1] + '" />';
  });
  html = html.replace(/<img[^>]*none\.gif[^>]*\/?>/g, '');
  html = html.replace(/<i class="pstatus">[\s\S]*?<\/i>/g, '');

  result = html;
}
